style.css:
h1, h2, h3, h4, h5 {
  position: relative;
  border: 2px solid transparent; /* Zapewnia, że ramki będą miały jednolitą grubość, nawet jeżeli nie będą miały koloru */
}

h1::before, h2::before, h3::before, h4::before, h5::before {
  content: attr(data-header-type);
  position: absolute;
  top: -1em; left: 0;
  font-size: 0.75em;
  color: white;
  padding: 2px 8px;
  border-radius: 3px;
}

h1 {
  border-color: #FF6347; /* Pomarańczowy */
}

h1::before {
  background-color: #FF6347;
  content: "H1";
}

h2 {
  border-color: #4682B4; /* Niebieski */
}

h2::before {
  background-color: #4682B4;
  content: "H2";
}

h3 {
  border-color: #32CD32; /* Zielony */
}

h3::before {
  background-color: #32CD32;
  content: "H3";
}

h4 {
  border-color: #FFD700; /* Złoty */
}

h4::before {
  background-color: #FFD700;
  content: "H4";
}

h5 {
  border-color: #C71585; /* Magneta */
}

h5::before {
  background-color: #C71585;
  content: "H5";
}
